 * Dosya      : hosting/php/src/Compliance.php
 * Açıklama   : Değişmez adres sürümleri, SKU/model belgeleri ve taşıyıcı kabulünün yetkili yönetimi.
 */
declare(strict_types=1);
namespace Sexogate;
final class Compliance
{
    public function __construct(private Database $db,private Config $config){}
    private function text(mixed $v,int $min=5,int $max=1000):string
    {RuleViolation::ensure(is_string($v)&&mb_strlen(trim($v))>=$min&&mb_strlen($v)<=$max,'INVALID_COMPLIANCE','Belge alanlarını ve inceleme kaynağını kontrol edin.',400);return trim($v);}
    private function country(string $code,bool $lock=false):void
    {RuleViolation::ensure($this->db->one('SELECT code FROM country_rules WHERE code=?'.($lock?' FOR UPDATE':''),[$code]),'COUNTRY_NOT_FOUND','Ülke bulunamadı.',404);}
    private function variant(string $id):void
    {$r=$this->db->one('SELECT product_id FROM variants WHERE id=?',[$id]);RuleViolation::ensure($r,'VARIANT_NOT_FOUND','Stok kodu bulunamadı.',404);$this->db->one('SELECT id FROM products WHERE id=? FOR UPDATE',[$r['product_id']]);$this->db->one('SELECT id FROM variants WHERE id=? FOR UPDATE',[$id]);}
    private function day(mixed $v):string
    {RuleViolation::ensure(is_string($v)&&preg_match('/\A\d{4}-\d{2}-\d{2}\z/',$v),'INVALID_DATE','Belge tarihini kontrol edin.',400);$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);RuleViolation::ensure($d&&$d->format('Y-m-d')===$v,'INVALID_DATE','Belge tarihi geçersiz.',400);return $v;}
    public function address(array $i,Principal $actor):array
    {
        $actor->require('settings',true);$country=$this->text($i['country']??null,2,2);$reference=$this->text($i['reference']??null);$fields=$i['fields']??null;RuleViolation::ensure(is_array($fields)&&array_is_list($fields)&&count($fields)>=3&&count($fields)<=7,'INVALID_ADDRESS_PROFILE','Adres profili üç ile yedi alan içermelidir.',400);$seen=[];
        foreach($fields as $f){RuleViolation::ensure(is_array($f)&&in_array($f['id']??null,['fullName','phone','line1','city','region','district','postalCode'],true)&&!isset($seen[$f['id']])&&is_bool($f['required']??null)&&is_int($f['minLength']??null)&&is_int($f['maxLength']??null)&&$f['minLength']>=0&&$f['maxLength']>=$f['minLength']&&$f['maxLength']>=1&&$f['maxLength']<=500&&in_array($f['format']??null,['text','digits','alphanumeric'],true),'INVALID_ADDRESS_PROFILE','Adres alanı, uzunluğu veya biçimi geçersiz.',400);foreach(['tr','en'] as $locale)$this->text($f['label'][$locale]??null,1,100);$seen[$f['id']]=true;}
        RuleViolation::ensure(isset($seen['fullName'],$seen['line1'],$seen['city']),'INVALID_ADDRESS_PROFILE','Alıcı adı, açık adres ve şehir alanları gerekir.',400);
        return $this->db->transaction(function()use($country,$reference,$fields,$actor){$this->country($country,true);$version=(int)$this->db->one('SELECT COALESCE(MAX(version),0) n FROM country_address_profiles WHERE country=?',[$country])['n']+1;$id=Database::id();$this->db->execute("INSERT INTO country_address_profiles(id,country,version,fields,reference,created_by) VALUES(?,?,?,?,?,?)",[$id,$country,$version,$this->config->json($fields),$reference,$actor->id]);(new Audit($this->db))->record($actor,'draft','address_profiles',$id,['version'=>$version]);return ['id'=>$id,'version'=>$version,'status'=>'draft'];});
    }
    public function approveAddress(string $id,Principal $actor):array
    {$actor->require('settings',true);return $this->db->transaction(function()use($id,$actor){$r=$this->db->one('SELECT country FROM country_address_profiles WHERE id=?',[$id]);RuleViolation::ensure($r,'ADDRESS_PROFILE_NOT_FOUND','Adres profili bulunamadı.',404);$this->country($r['country'],true);$r=$this->db->one('SELECT * FROM country_address_profiles WHERE id=? FOR UPDATE',[$id]);RuleViolation::ensure($r['status']==='draft','ADDRESS_PROFILE_STATE','Yalnız taslak profil onaylanabilir.');$this->db->execute("UPDATE country_address_profiles SET status='archived' WHERE country=? AND status='approved'",[$r['country']]);$this->db->execute("UPDATE country_address_profiles SET status='approved',approved_by=?,approved_at=CURRENT_TIMESTAMP(3) WHERE id=?",[$actor->id,$id]);(new Audit($this->db))->record($actor,'approve','address_profiles',$id);return ['id'=>$id,'status'=>'approved'];});}
    public function eligibility(array $i,Principal $actor):array
    {$actor->require('settings',true);$variant=$this->text($i['variantId']??null,1,128);$country=$this->text($i['country']??null,2,2);$reference=$this->text($i['reference']??null);$kind=($i['requiredDocumentKind']??null)?:null;RuleViolation::ensure($kind===null||(is_string($kind)&&preg_match('/\A[a-z0-9-]{1,100}\z/',$kind)),'INVALID_DOCUMENT_KIND','Belge türünü kontrol edin.',400);return $this->db->transaction(function()use($variant,$country,$reference,$kind,$actor){$this->variant($variant);$this->country($country);$this->db->execute('INSERT INTO product_eligibility(variant_id,country,required_document_kind,review_note) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE approved=false,required_document_kind=VALUES(required_document_kind),review_note=VALUES(review_note),approved_by=NULL,approved_at=NULL',[$variant,$country,$kind,$reference]);(new Audit($this->db))->record($actor,'requirements','product_eligibility',$variant,['country'=>$country,'kind'=>$kind]);return ['variantId'=>$variant,'country'=>$country,'approved'=>false];});}
    public function document(array $i,Principal $actor):array
    {
        $actor->require('settings',true);$variant=$this->text($i['variantId']??null,1,128);$country=$this->text($i['country']??null,2,2);$kind=$i['kind']??'';RuleViolation::ensure(is_string($kind)&&preg_match('/\A[a-z0-9-]{1,100}\z/',$kind),'INVALID_DOCUMENT_KIND','Belge türünü kontrol edin.',400);$model=$this->text($i['modelReference']??null,1,300);$reference=$this->text($i['reference']??null);$from=$this->day($i['validFrom']??null);$until=empty($i['validUntil'])?null:$this->day($i['validUntil']);RuleViolation::ensure($until===null||$until>=$from,'INVALID_VALIDITY','Belgenin tarih aralığını kontrol edin.',400);
        return $this->db->transaction(function()use($variant,$country,$kind,$model,$reference,$from,$until,$actor){$this->variant($variant);$this->country($country);$version=(int)$this->db->one('SELECT COALESCE(MAX(version),0) n FROM product_documents WHERE variant_id=? AND country=? AND kind=?',[$variant,$country,$kind])['n']+1;$id=Database::id();$this->db->execute('INSERT INTO product_documents(id,variant_id,country,kind,reference,valid_from,valid_until,model_reference,version,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)',[$id,$variant,$country,$kind,$reference,$from,$until,$model,$version,$actor->id]);(new Audit($this->db))->record($actor,'draft','product_documents',$id,['version'=>$version]);return ['id'=>$id,'version'=>$version];});
    }
    private function lockDocument(string $id):array
    {$r=$this->db->one('SELECT variant_id FROM product_documents WHERE id=?',[$id]);RuleViolation::ensure($r,'DOCUMENT_NOT_FOUND','Belge bulunamadı.',404);$this->variant($r['variant_id']);return $this->db->one('SELECT * FROM product_documents WHERE id=? FOR UPDATE',[$id]);}
    public function reviewDocument(string $id,string $note,Principal $actor):array
    {$actor->require('settings',true);$note=$this->text($note);return $this->db->transaction(function()use($id,$note,$actor){$r=$this->lockDocument($id);$today=(new CheckoutPolicy($this->db,$this->config))->countryDay($r['country']);$latest=(int)$this->db->one('SELECT MAX(version) n FROM product_documents WHERE variant_id=? AND country=? AND kind=?',[$r['variant_id'],$r['country'],$r['kind']])['n'];RuleViolation::ensure($r['revoked_at']===null&&$r['model_reference']!==''&&(int)$r['version']===$latest&&$r['valid_from']<=$today&&($r['valid_until']===null||$r['valid_until']>=$today),'DOCUMENT_NOT_REVIEWABLE','Son belge sürümü, model kapsamı ve geçerlilik tarihleri doğrulanmalıdır.');$this->db->execute("UPDATE product_documents SET reviewed=false,revoked_by=?,revoked_at=CURRENT_TIMESTAMP(3),revocation_reason='Yeni incelenmiş belge sürümüyle değiştirildi' WHERE variant_id=? AND country=? AND kind=? AND id<>? AND reviewed=true",[$actor->id,$r['variant_id'],$r['country'],$r['kind'],$id]);$this->db->execute('UPDATE product_documents SET reviewed=true,reviewed_by=?,reviewed_at=CURRENT_TIMESTAMP(3),review_note=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$actor->id,$note,$id]);(new Audit($this->db))->record($actor,'review','product_documents',$id);return ['id'=>$id,'reviewed'=>true];});}
    public function revokeDocument(string $id,string $reason,Principal $actor):array
    {$actor->require('settings',true);$reason=$this->text($reason);return $this->db->transaction(function()use($id,$reason,$actor){$r=$this->lockDocument($id);$this->db->execute('UPDATE product_documents SET reviewed=false,revoked_by=?,revoked_at=CURRENT_TIMESTAMP(3),revocation_reason=?,updated_at=CURRENT_TIMESTAMP(3) WHERE id=?',[$actor->id,$reason,$id]);$this->db->execute('UPDATE product_eligibility SET approved=false,approved_by=NULL,approved_at=NULL WHERE variant_id=? AND country=? AND required_document_kind=?',[$r['variant_id'],$r['country'],$r['kind']]);(new Audit($this->db))->record($actor,'revoke','product_documents',$id);return ['id'=>$id,'reviewed'=>false];});}
    public function carrier(array $i,Principal $actor):array
    {
        $actor->require('settings',true);$variant=$this->text($i['variantId']??null,1,128);$country=$this->text($i['country']??null,2,2);$carrier=$this->text($i['carrier']??null,2,191);$reference=$this->text($i['reference']??null);$accepted=($i['accepted']??false)===true;RuleViolation::ensure(is_string($i['validUntil']??null)&&preg_match('/\A\d{4}-\d{2}-\d{2}T/',$i['validUntil']),'INVALID_DATE','Taşıyıcı kabulünün geçerlilik tarihini kontrol edin.',400);try{$until=new \DateTimeImmutable($i['validUntil']);}catch(\Throwable){throw new RuleViolation('INVALID_DATE','Tarih geçersiz.',400);}RuleViolation::ensure(!$accepted||($until->getTimestamp()>time()&&$until->getTimestamp()<=time()+31622400),'INVALID_VALIDITY','Taşıyıcı kabulü en fazla bir yıl geçerli olabilir.',400);
        return $this->db->transaction(function()use($variant,$country,$carrier,$reference,$accepted,$until,$actor){$this->variant($variant);$this->country($country);$this->db->execute('INSERT INTO shipping_approvals(variant_id,country,carrier,accepted,reviewed_by,reference,valid_until) VALUES(?,?,LOWER(?),?,?,?,?) ON DUPLICATE KEY UPDATE accepted=VALUES(accepted),reviewed_by=VALUES(reviewed_by),reference=VALUES(reference),valid_until=VALUES(valid_until)',[$variant,$country,$carrier,(int)$accepted,$actor->id,$reference,$until->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s.v')]);(new Audit($this->db))->record($actor,'carrier-review','product_eligibility',$variant,['country'=>$country,'carrier'=>$carrier,'accepted'=>$accepted,'reference'=>$reference]);return ['variantId'=>$variant,'country'=>$country,'accepted'=>$accepted];});
    }
    public function listing(Principal $actor):array
    {$actor->require('settings');return ['profiles'=>$this->db->all('SELECT id,country,version,status,reference,fields FROM country_address_profiles ORDER BY created_at DESC LIMIT 100'),'documents'=>$this->db->all('SELECT d.*,v.sku FROM product_documents d JOIN variants v ON v.id=d.variant_id ORDER BY d.created_at DESC LIMIT 100'),'eligibility'=>$this->db->all('SELECT e.*,v.sku FROM product_eligibility e JOIN variants v ON v.id=e.variant_id ORDER BY v.sku,e.country LIMIT 200'),'carriers'=>$this->db->all('SELECT a.*,v.sku FROM shipping_approvals a JOIN variants v ON v.id=a.variant_id ORDER BY a.created_at DESC LIMIT 100')];}
}
